import { readFileSync, writeFileSync } from "node:fs";
import { dataSchema } from "../lib/data";
const result = dataSchema.safeParse(
  JSON.parse(
    readFileSync(
      new URL("../data/campus-locations.json", import.meta.url),
      "utf8",
    ),
  ),
);
if (!result.success) {
  console.error("Invalid campus location data:", result.error.format());
  process.exit(1);
}
const gaps = result.data.filter((p) => p.lat === null || !p.verified);
writeFileSync(
  new URL("../DATA_GAPS.md", import.meta.url),
  "# Campus data gaps\n\nGenerated by `npm run validate-data`. Google listings do not establish on-campus verification. Accessibility is unconfirmed; false means no confirmed accessible route.\n\n" +
    gaps
      .map(
        (p) =>
          `- **${p.name}** (${p.id}): ${p.lat === null ? "coordinates pending" : "Google coordinates supplied"}; campus verification pending. Source: ${p.source}.`,
      )
      .join("\n") +
    "\n",
);
console.log(
  `Validated ${result.data.length} locations; ${gaps.length} need campus confirmation.`,
);
